const body = $input.first().json.body;
const appUrl = process.env.APP_URL || 'https://app.cmmc4msp.on-nex.us';
const inviteUrl = `${appUrl}/invite/${body.invite_token}`;

return [{
  json: {
    email: body.email,
    invite_token: body.invite_token,
    org_name: body.org_name,
    invited_by_name: body.invited_by_name,
    role: body.role,
    invite_url: inviteUrl,
    expires_in_hours: 72,
  }
}];
